    for (let x = 1; x < 63; x += 6) { pix(x + 2, 12, C.ink); pix(x + 3, 13, C.ink); }
    rect(2, 30, 60, 14, C.ink); rect(3, 31, 58, 12, C.brown); hline(3, 31, 58, C.tan);
