    for (let i = 0; i <= 7; i++) pix(2 + i, 9 - i, C.sand);
    for (let i = 0; i <= 5; i++) pix(3 + i, 3 + i, C.lgray);
    pix(2, 2, C.white); pix(3, 2, C.white); pix(2, 3, C.white); pix(8, 9, C.red); pix(9, 8, C.red); pix(9, 9, C.red);
    addOutline(c, C.ink);
