          g.globalAlpha = 0.85; ellipse(cx, sy + bob, lw / 2 - 2, 5, C.slate); ellipse(cx - 5, sy - 2 + bob, 6, 4, C.gray); ellipse(cx + 5, sy - 2 + bob, 6, 4, C.gray); ellipse(cx, sy - 3 + bob, 7, 4, C.lgray);
