    button('sk_reset', P.x + P.w - 60, y - 2, 52, 12, TX('SIFIRLA'), () => { META.points += spent; META.skills = {}; saveMeta(); Sound.play('select'); }, { kind: 'secondary', disabled: spent === 0 });
    y += 13;
